effect.shader:
float lumaAt(vec2 uv) {
    return dot(texture(inputImg, clamp(uv, 0.0, 1.0)).rgb, vec3(0.299, 0.587, 0.114));
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);
    vec2 texel = acTexelSize * thickness * acEscalaDePixel;

    float tl = lumaAt(acScreenNorm + vec2(-texel.x, -texel.y));
    float tc = lumaAt(acScreenNorm + vec2(     0.0, -texel.y));
    float tr = lumaAt(acScreenNorm + vec2( texel.x, -texel.y));
    float ml = lumaAt(acScreenNorm + vec2(-texel.x,      0.0));
    float mr = lumaAt(acScreenNorm + vec2( texel.x,      0.0));
    float bl = lumaAt(acScreenNorm + vec2(-texel.x,  texel.y));
    float bc = lumaAt(acScreenNorm + vec2(     0.0,  texel.y));
    float br = lumaAt(acScreenNorm + vec2( texel.x,  texel.y));

    float gx = (tr + 2.0 * mr + br) - (tl + 2.0 * ml + bl);
    float gy = (bl + 2.0 * bc + br) - (tl + 2.0 * tc + tr);

    float edge = clamp(sqrt(gx * gx + gy * gy) * gain, 0.0, 1.0);
    vec3 drawn = mix(fillColor.rgb, lineColor.rgb, edge);

    fragColor = vec4(drawn, original.a);
}
